// protobufjs static-module's ONEOF ACCESSOR idiom, reduced but verbatim in
// shape. This is the construct family behind 44 of the 45 `Object.defineProperty`
// refusals in the QR-path closure of a real generated protobuf bundle:
//
//   Object.defineProperty(Msg.prototype, "_field", {
//     get: util.oneOfGetter(f = ["field"]), set: util.oneOfSetter(f)
//   });
//
// Four things refuse here, and the ORDER matters more than the count. The
// `Object.defineProperty` fence is the one a census sees, but it is masking
// the RECEIVER: `Msg.prototype` is not a value in this IR (method lookup is
// static), so a descriptor-side lowering would uncover the receiver at the
// same statement and buy nothing. The pin in npm-static.test.ts records all
// four, so the frontier only moves deliberately.
//
// oneOfGetter / oneOfSetter are protobufjs/src/util.js verbatim, reflowed.
function oneOfGetter(fieldNames) {
  var fieldMap = {};
  for (var i = 0; i < fieldNames.length; ++i) fieldMap[fieldNames[i]] = 1;
  return function () {
    for (var keys = Object.keys(this), i = keys.length - 1; i > -1; --i)
      if (fieldMap[keys[i]] === 1 && this[keys[i]] !== undefined && this[keys[i]] !== null)
        return keys[i];
  };
}

function oneOfSetter(fieldNames) {
  return function (name) {
    for (var i = 0; i < fieldNames.length; ++i)
      if (fieldNames[i] !== name) delete this[fieldNames[i]];
  };
}

// pbjs's message constructor: own properties are ONLY the non-null keys the
// caller passed, and the prototype carries the null defaults. The oneof
// getter's answer is a function of that own-property SET, which is why a
// static layout (every field always present) cannot stand in for it.
function Payload(p) {
  if (p)
    for (var ks = Object.keys(p), i = 0; i < ks.length; ++i)
      if (p[ks[i]] != null && ks[i] !== "__proto__") this[ks[i]] = p[ks[i]];
}
Payload.prototype.username = null;
Payload.prototype.passive = null;

var g;
// A SINGLE-member group — 153 of 153 sites in the real QR closure are this,
// because proto3 `optional` synthesizes a one-member oneof per field.
Object.defineProperty(Payload.prototype, "_username", {
  get: oneOfGetter((g = ["username"])),
  set: oneOfSetter(g),
});
// A MULTI-member group — a declared oneof. Its setter DELETES the losing
// members, which is the observable half of the family.
Object.defineProperty(Payload.prototype, "content", {
  get: oneOfGetter((g = ["username", "passive"])),
  set: oneOfSetter(g),
});

// Construction stays INSIDE the package: `new Payload(...)` spelled in the
// program would make the opt-in fall back to the island before any of this
// is reachable ([[Construct]] on a plain JS function is its own refusal).
function create(p) {
  return new Payload(p);
}

// pbjs `encode` — note it reads the DATA fields through the own-property
// predicate, never the accessor.
function encode(m) {
  var out = [];
  if (m.username != null && Object.hasOwnProperty.call(m, "username")) out.push("u=" + m.username);
  if (m.passive != null && Object.hasOwnProperty.call(m, "passive")) out.push("p=" + m.passive);
  return out.join(",");
}

module.exports = { create: create, encode: encode };
